<script setup>import{inject,ref}from'vue';import api from '../../../../services/api';import AddBranchModal from '../../../../components/admin/AddBranchModal.vue';const s=inject('clinicAdmin'),open=ref(false);function close(){open.value=false;s.error.value=null}async function add(name){try{await s.run(async()=>{await api.post('/v1/platform/tenants/'+s.clinic.value.id+'/branches',{name});await s.load(s.clinic.value.id)},'Branch created.');open.value=false}catch{}}</script><template><section class="admin-card"><div class="card-heading"><div><h2>Branches</h2><p class="text-sm text-slate-500">Locations belonging to this clinic.</p></div><button class="btn" @click="open=true">+ Add Branch</button></div><div class="table-wrap"><table><thead><tr><th>Branch</th><th>Location</th><th>Members</th><th>Status</th></tr></thead><tbody><tr v-for="branch in s.branches.value" :key="branch.id"><td class="font-semibold">{{branch.name}}</td><td>Not recorded</td><td>Not available</td><td><span class="badge badge-green">Active</span></td></tr></tbody></table></div><AddBranchModal :open="open" @close="close" @save="add"/></section></template>
